package zw.chibaro;
import java.util.*;
import java.time.*;
import jakarta.validation.constraints.*;
import tools.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.server.ResponseStatusException;
import static org.springframework.http.HttpStatus.*;
@Service
public class MarketingService {
 final JdbcTemplate db;final AiProvider ai;final TransactionTemplate tx;final int limit;final String provider;
 public MarketingService(JdbcTemplate db,AiProvider ai,TransactionTemplate tx,@Value("${app.ai-monthly-limit}")int limit,@Value("${app.ai-provider}")String provider){this.db=db;this.ai=ai;this.tx=tx;this.limit=limit;this.provider=provider;}
 public record Draft(@NotBlank @Size(max=200) String heading,@NotBlank @Size(max=5000) String caption,@NotNull @Size(max=1000) String hashtags,@NotNull @Pattern(regexp="FACEBOOK|INSTAGRAM|LINKEDIN|POSTER")String platform,UUID campaignId){}
 public record Generate(@NotBlank @Size(max=2000)String instructions,@NotNull @Pattern(regexp="FACEBOOK|INSTAGRAM|LINKEDIN|POSTER")String platform){}
 public record Campaign(@NotBlank @Size(max=150)String name,@NotBlank @Size(max=2000)String instructions){}
 public record Schedule(@NotNull @Future Instant scheduledAt,@NotNull UUID accountId){}
 @Transactional public Map<String,Object> save(Draft r,UUID id,String actor){UUID post=id==null?UUID.randomUUID():id;policy(r.heading()+" "+r.caption()+" "+r.hashtags());if(id==null)db.update("insert into marketing_posts(id,campaign_id,platform,heading,caption,hashtags) values (?,?,?,?,?,?)",post,r.campaignId(),r.platform(),r.heading(),r.caption(),r.hashtags());else{int changed=db.update("update marketing_posts set heading=?,caption=?,hashtags=?,platform=?,campaign_id=?,status='DRAFT',approved_by=null,approved_at=null where id=? and status in ('DRAFT','APPROVED')",r.heading(),r.caption(),r.hashtags(),r.platform(),r.campaignId(),post);if(changed==0)throw new ResponseStatusException(CONFLICT,"Only drafts and unscheduled approved posts can be edited.");}SecurityConfig.audit(db,actor,"POST_SAVED",post.toString());return Map.of("id",post,"status","DRAFT");}
 static void policy(String text){String lower=text.toLowerCase(Locale.ROOT);if(lower.matches("(?s).*(guaranteed|same.day|discount|cheapest|south africa|botswana|\\$[0-9]|[0-9]+%).*"))throw new ResponseStatusException(BAD_REQUEST,"Content contains a claim requiring verified business rules. Remove unsupported prices, discounts, guarantees or destinations.");}
 public Map<String,Object> generate(Generate r,String actor){if(provider.equals("disabled"))throw new ResponseStatusException(SERVICE_UNAVAILABLE,"AI integration setup required.");UUID usage=tx.execute(status->{db.queryForObject("select pg_advisory_xact_lock(78234311)",Object.class);long used=db.queryForObject("select count(*) from ai_usage_records where created_at>=date_trunc('month',now())",Long.class);if(used>=limit)throw new ResponseStatusException(TOO_MANY_REQUESTS,"Monthly AI generation limit reached.");UUID id=UUID.randomUUID();db.update("insert into ai_usage_records(id,provider,status) values (?,?,'RESERVED')",id,provider);return id;});try{String context="Name: TransChibaro Logistics. Location: Beitbridge, Zimbabwe. WhatsApp +263 77 500 8064. Truck specification 3000 kg; all loads subject to review. Rates by individual quotation only. Services: "+db.queryForList("select name,description from business_services where active")+". Verified areas: "+db.queryForList("select name from service_areas where verified");String raw=ai.generate(context,"Platform: "+r.platform()+". Creative instructions: "+r.instructions());var root=new ObjectMapper().readTree(raw);if(root.size()!=3||!root.path("heading").isTextual()||!root.path("caption").isTextual()||!root.path("hashtags").isTextual())throw new IllegalArgumentException();var draft=new Draft(root.path("heading").asText(),root.path("caption").asText(),root.path("hashtags").asText(),r.platform(),null);if(draft.heading().isBlank()||draft.heading().length()>200||draft.caption().isBlank()||draft.caption().length()>5000||draft.hashtags().length()>1000)throw new IllegalArgumentException();policy(draft.heading()+" "+draft.caption()+" "+draft.hashtags());Map<String,Object> saved=tx.execute(status->save(draft,null,actor));db.update("update ai_usage_records set status='SUCCEEDED' where id=?",usage);return saved;}catch(ResponseStatusException ex){db.update("update ai_usage_records set status='FAILED' where id=?",usage);throw ex;}catch(Exception ex){db.update("update ai_usage_records set status='FAILED' where id=?",usage);throw new ResponseStatusException(BAD_GATEWAY,"Generated content failed validation; no draft was saved.");}}
 @Transactional public void approve(UUID id,String actor){var rows=db.queryForList("select * from marketing_posts where id=? for update",id);if(rows.isEmpty())throw new ResponseStatusException(NOT_FOUND);var post=rows.getFirst();policy(post.get("heading")+" "+post.get("caption")+" "+post.get("hashtags"));if(!Set.of("DRAFT","APPROVED").contains(post.get("status")))throw new ResponseStatusException(CONFLICT,"Post cannot be approved in its current state.");db.update("update marketing_posts set status='APPROVED',approved_by=?,approved_at=now() where id=?",actor,id);SecurityConfig.audit(db,actor,"POST_APPROVED",id.toString());}
 @Transactional public void schedule(UUID id,Schedule r,String actor){var posts=db.queryForList("select p.* from marketing_posts p join marketing_campaigns c on c.id=p.campaign_id where p.id=? and p.status='APPROVED' and c.approved for update of p",id);if(posts.isEmpty())throw new ResponseStatusException(CONFLICT,"Approve both the post and its campaign before scheduling.");var accounts=db.queryForList("select id from social_accounts where id=? and status='CONNECTED' and token_expires_at>now() and provider=?",r.accountId(),posts.getFirst().get("platform"));if(accounts.isEmpty())throw new ResponseStatusException(CONFLICT,"Integration setup required: a verified connected account is required.");throw new ResponseStatusException(SERVICE_UNAVAILABLE,"Direct publishing is disabled until OAuth, permissions and provider reconciliation pass verification.");}
}
